require_once __DIR__.'/../includes/bootstrap.php';$uid=(int)($_SESSION['password_reset_user']??0);if(!$uid){flash('error','Start password recovery first.');redirect('forgot-password.php');}$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$code=trim((string)($_POST['code']??''));$password=(string)($_POST['password']??'');$confirm=(string)($_POST['confirm_password']??'');$errors=array_merge($errors,password_policy_errors($password));if($password!==$confirm)$errors[]='Passwords do not match.';$q=db()->prepare('SELECT * FROM password_resets WHERE user_id=? AND expires_at>NOW() ORDER BY id DESC LIMIT 1');$q->execute([$uid]);$r=$q->fetch();if(!$r)$errors[]='The reset request expired. Start again.';elseif((int)$r['attempts']>=5)$errors[]='Too many incorrect attempts. Start password recovery again.';elseif(!preg_match('/^[0-9]{6}$/',$code)||!password_verify($code,$r['code_hash'])){$errors[]='The verification code is incorrect.';db()->prepare('UPDATE password_resets SET attempts=attempts+1 WHERE id=?')->execute([$r['id']]);}if(!$errors){db()->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($password,PASSWORD_DEFAULT),$uid]);db()->prepare('DELETE FROM password_resets WHERE user_id=?')->execute([$uid]);unset($_SESSION['password_reset_user'],$_SESSION['password_reset_method']);flash('success','Your password has been changed. You can now log in.');redirect('login.php');}}$pageTitle='Set a new password';require __DIR__.'/../includes/header.php';?><section class="auth-layout"><div class="auth-aside"><span class="eyebrow">SECURE ACCOUNT RECOVERY</span><h1>Choose a new password.</h1><p>Confirm the code sent to your selected contact method.</p></div><div class="form-panel"><div class="form-heading"><h2>Reset password</h2></div><?php if($errors):?><div class="alert alert-error"><ul><?php foreach($errors as $error):?><li><?=e($error)?></li><?php endforeach;?></ul></div><?php endif;?><form method="post" class="stack-form" data-password-policy><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>6-digit verification code<input name="code" required pattern="[0-9]{6}" minlength="6" maxlength="6" inputmode="numeric"></label><label>New password<span class="password-wrap"><input type="password" name="password" required minlength="10" data-password-main><button class="password-toggle" type="button" data-password-toggle>Show</button></span><small class="password-rules" data-password-rules>10+ characters, uppercase, lowercase, digit and symbol.</small></label><label>Confirm new password<span class="password-wrap"><input type="password" name="confirm_password" required minlength="10" data-password-confirm><button class="password-toggle" type="button" data-password-toggle>Show</button></span><small class="password-rules" data-confirm-hint></small></label><button class="button button-full" type="submit">Change password →</button></form></div></section><?php require __DIR__.'/../includes/footer.php';?>